 } \matrix{
   { - 1 - {{\sin }^2}\theta }  \cr 
   {{{\cos }^4}\theta }  \cr 

 } } \right] = \left[ {\matrix{
   \alpha   \cr 
   0  \cr 

 } \,\matrix{
   0  \cr 
   \alpha   \cr 

 } } \right]$$ + {\beta  \over {\left| M \right|}}(adj\,M)$$

$$ \because $$ $$\left[ {{M^{ - 1}} = {{adj\,M} \over {\left| M \right|}}} \right]$$

$$ \Rightarrow $$ $$\left[ {\matrix{
   {{{\sin }^4}\theta }  \cr 
   {1 + {{\cos }^2}\theta }  \cr 

 } \matrix{
   { - 1 - {{\sin }^2}\theta }  \cr 
   {{{\cos }^4}\theta }  \cr 

 } } \right] = \left[ {\matrix{
   \alpha   \cr 
   0  \cr 

 } \,\matrix{
   0  \cr 
   \alpha   \cr 

 } } \right] + {\beta  \over {\left| M \right|}}\left[ {\matrix{
   {{{\cos }^4}\theta }  \cr 
   { - 1 - {{\cos }^2}\theta }  \cr 

 } \matrix{
   {1 + {{\sin }^2}\theta }  \cr 
   {{{\sin }^4}\theta }  \cr 

 } } \right]$$

$$ \because $$ $$\left\{ {adj\left[ {\matrix{
   a &amp; b  \cr 
   c &amp; d  \cr 

 } } \right] = \left[ {\matrix{
   d &amp; { - b}  \cr 
   { - c} &amp; a  \cr 

 } } \right]} \right\}$$

$$ \Rightarrow \beta  =  - \left| M \right|$$ and $$\alpha  = {\sin ^4}\theta  + {\cos ^4}\theta $$

$$ \Rightarrow \alpha  = \alpha (\theta ) = 1 - {1 \over 2}{\sin ^2}(2\theta )$$, and $$\beta  = \beta (\theta ) =  - \left\{ {{{\left( {{{\sin }^2}\theta {{\cos }^2}\theta  + {1 \over 2}} \right)}^2} + {7 \over 4}} \right\} =  - \left\{ {{{\left( {{{{{\sin }^2}(2\theta )} \over 4} + {1 \over 2}} \right)}^2} + {7 \over 4}} \right\}$$

Now, ${\alpha ^*} = {\alpha _{\min }} = {1 \over 2}$$

and ${\beta ^*} = {\beta _{\min }} =  - {{37} \over {16}}$$

$$ \because $$ $$\alpha $$ is minimum at sin<sup>2</sup>(2$$\theta $$) = 1 and $$\beta $$ is minimum at sin<sup>2</sup>(2$$\theta $$) = 1

So, ${\alpha ^*} + {\beta ^*} = {1 \over 2} - {{37} \over {16}} =  - {{29} \over {16}}$$

