   3 &amp; b &amp; 1  \cr 

 } } \right] = {{|M|} \over 4}\left[ {\matrix{
   0 &amp; { - 2} &amp; { - 4}  \cr 
   { - 2} &amp; { - 4} &amp; { - 6}  \cr 
   { - 6} &amp; { - 2} &amp; { - 2}  \cr 

 } } \right]$$

$$ \Rightarrow $$ M = $$\left[ {\matrix{
